mapper.select:
SELECT * FROM behavior_log
WHERE user_id = #{userId}
ORDER BY id DESC
LIMIT #{limit}

SELECT b2.product_id, SUM(b2.score) AS agg_score, COUNT(DISTINCT b1.user_id) AS agg_users FROM behavior_log b1 JOIN behavior_log b2 ON b1.user_id = b2.user_id AND b2.product_id != b1.product_id AND b1.user_id != #{excludeUserId} WHERE b1.product_id IN
#{pid}
GROUP BY b2.product_id ORDER BY agg_score DESC LIMIT #{limit}
